bg=6
patterns={1:[[0,0,1],[1,1,1],[0,0,1]],3:[[0,1,1],[0,1,1],[1,0,0]],7:[[0,1,1],[1,1,0],[0,0,1]],5:[[0,1,1],[1,1,0],[0,1,1]]}
layout=[[1,3],[7,5]]
out=[[bg]*13 for _ in range(13)]
for ti,row in enumerate(layout):
    r0=1+ti*6
    for tj,col in enumerate(row):
        c0=1+tj*6
        p=patterns[col]
        for r in range(5):
            for c in range(5):
                out[r0+r][c0+c]=bg if (1<=r<=3 and 1<=c<=3 and p[r-1][c-1]) else col
print('\n'.join(' '.join(map(str,r)) for r in out))
